<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x968F;&#x673A;&#x59D3;&#x540D;</text><text class="nav-icon" @click="generate">&#x1F504;</text></view></view><view class="content"><view class="options"><view class="opt-row"><text class="opt-label">&#x8BED;&#x8A00;</text><view class="opt-btns"><view class="opt-btn" v-for="l in langs" :key="l.v" :class="{active: lang===l.v}" @click="lang=l.v">{{l.t}}</view></view></view><view class="opt-row"><text class="opt-label">&#x6027;&#x522B;</text><view class="opt-btns"><view class="opt-btn" :class="{active: gender==='all'}" @click="gender='all'">&#x5168;&#x90E8;</view><view class="opt-btn" :class="{active: gender==='male'}" @click="gender='male'">&#x7537;</view><view class="opt-btn" :class="{active: gender==='female'}" @click="gender='female'">&#x5973;</view></view></view><view class="opt-row"><text class="opt-label">&#x6570;&#x91CF;</text><view class="opt-btns"><view class="opt-btn" v-for="n in [5,10,20]" :key="n" :class="{active: count===n}" @click="count=n">{{n}}</view></view></view></view><view class="generate-btn" @click="generate"><text>&#x751F;&#x6210;&#x59D3;&#x540D;</text></view><view v-if="names.length" class="name-list"><view class="name-item" v-for="(name, idx) in names" :key="idx" @click="copyText(name)">{{ name }}</view></view><view v-if="names.length" class="copy-all-btn" @click="copyAll"><text>&#x590D;&#x5236;&#x5168;&#x90E8;</text></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const lang = ref("zh")
const gender = ref("all")
const count = ref(10)
const names = ref([])
const langs = [{v:"zh",t:"&#x4E2D;&#x6587"},{v:"en",t:"&#x82F1;&#x6587"},{v:"jp",t:"&#x65E5;&#x6587"},{v:"kr",t:"&#x97E9;&#x6587"}]
const surnames = "&#x738B;&#x674E;&#x5F20;&#x5218;&#x9648;&#x6768;&#x8D75;&#x9EC4;&#x5468;&#x5434;&#x5F90;&#x5B59;&#x80E1;&#x6731;&#x9AD8;&#x6797;&#x90ED;&#x4F55;&#x9A6C;&#x7F57;&#x5B8B;&#x8BB8;&#x90B5;&#x6C88;&#x97E9;&#x6881;&#x94C1;"
const maleNames = "&#x4F1F;&#x521A;&#x8F89;&#x6D69;&#x8FC5;&#u5F3A\u5E73\u5EF7\u5EFA\u8D85\u660E\u96C4\u96F7\u9E3F\uu5CF0\u680B\u68EE"
const femaleNames = "&#u82B3\u5A77\u5A1C\u598D\u5A34\u5B87\u6DD1\u7B11\u59FF\u5029\u5B81\u7B60\u541B\u971E"
const enFirst = ["James","John","Robert","Michael","William","David","Richard","Joseph","Thomas","Charles","Mary","Patricia","Jennifer","Linda","Barbara","Elizabeth","Sarah","Karen","Lisa","Nancy"]
const enLast = ["Smith","Johnson","Williams","Brown","Jones","Garcia","Miller","Davis","Rodriguez","Martinez","Anderson","Taylor","Thomas","Moore","Jackson","Martin"]
const jpNames = ["\u68EE\u5DDD \u7D14\u4E00","\u7530\u4E2D \u592A\u90CE","\u4F0A\u85E4 \u5065\u592A","\u6E21\u9089 \u7FA9\u9060","\u5C0F\u6797 \u6625\u9999"]
const krNames = "\u91D1\u79C0\u8D24\u6734\u660E\u73E0\u8D75\u9756\u60E0\u5B59\u826F\u5B50"
function goBack() { uni.navigateBack() }
function generate() { names.value = []; for (var i = 0; i < count.value; i++) names.value.push(genName()) }
function genName() { if (lang.value === "zh") { var s = surnames[Math.floor(Math.random()*surnames.length)]; var pool = gender.value==="all" ? maleNames+femaleNames : gender.value==="male" ? maleNames : femaleNames; return s + pool[Math.floor(Math.random()*pool.length)] + (Math.random()>0.5?pool[Math.floor(Math.random()*pool.length)]:"") } else if (lang.value === "en") { return enFirst[Math.floor(Math.random()*enFirst.length)] + " " + enLast[Math.floor(Math.random()*enLast.length)] } else if (lang.value === "jp") { return jpNames[Math.floor(Math.random()*jpNames.length)] } else { var f = ["\u6734\u91D1\u674E\u8D75\u97E9","\u79C0\u83C1\u660E\u5B50\u9756\u5929\u60E0"]; return f[Math.floor(Math.random()*f.length)] + krNames[Math.floor(Math.random()*krNames.length)] } }
function copyText(t) { uni.setClipboardData({ data: t, success: function() { uni.showToast({ title: "&#x5DF2;&#x590D;&#x5236;", icon: "success" }) } }) }
function copyAll() { uni.setClipboardData({ data: names.value.join(", "), success: function() { uni.showToast({ title: "&#x5DF2;&#x590D;&#x5236;&#x5168;&#x90E8;", icon: "success" }) } }) }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } generate() })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#6366f1,#4f46e5);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.options{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:16rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.opt-row{margin-bottom:16rpx}.opt-label{font-size:26rpx;color:#666;display:block;margin-bottom:8rpx}.opt-btns{display:flex;gap:8rpx}.opt-btn{flex:1;padding:12rpx;text-align:center;background:#f5f7fb;border-radius:8rpx;font-size:24rpx;color:#666}.opt-btn.active{background:linear-gradient(135deg,#6366f1,#4f46e5);color:#fff}.generate-btn{background:linear-gradient(135deg,#6366f1,#4f46e5);border-radius:16rpx;padding:24rpx;text-align:center;margin-bottom:16rpx}.generate-btn text{font-size:30rpx;color:#fff;font-weight:600}.name-list{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:16rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.name-item{padding:16rpx;border-bottom:1rpx solid #f0f0f0;font-size:30rpx;color:#333}.name-item:last-child{border:none}.copy-all-btn{background:#eef2ff;border-radius:16rpx;padding:20rpx;text-align:center}.copy-all-btn text{font-size:28rpx;color:#4f46e5;font-weight:600}</style>